// When the page content is ready...
document.addEventListener("DOMContentLoaded", () => {
    // Check URL for lang parameter
    const urlParams = new URLSearchParams(window.location.search);
    const urlLang = urlParams.get('lang');
    const savedLocale = localStorage.getItem('locale');
    const initialLocale = urlLang || savedLocale || locale; // urlLang first, then saved, then default
    setLocale(initialLocale);
    bindLocaleSwitcher(initialLocale); // Bind the locale switcher dropdown
});

// Set the locale and update translations
function setLocale(newLocale) {
    if (translations[newLocale]) {
        locale = newLocale;
        localStorage.setItem('locale', newLocale); // Save last selected locale
        updateContent();
        // Optional: update direction if needed
    }
}

// Update the page content with the selected locale
function updateContent() {
    document.querySelectorAll("[data-i18n]").forEach((element) => {
        const key = element.getAttribute("data-i18n");
        element.textContent = translations[locale][key]; // Update content
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(elem => {
        const key = elem.getAttribute('data-i18n-placeholder');
        elem.placeholder = translations[locale][key] || key;
    });
    document.querySelectorAll(".error-msg[data-error-key]").forEach(elem => {
        const key = elem.getAttribute("data-error-key");
        elem.textContent = translations[locale][key] || key;
    });
}

// Update text direction based on locale (LTR or RTL)


// Bind the locale switcher dropdown to dynamically update locale
function bindLocaleSwitcher(initialValue) {
    const switcher = document.querySelector("[data-i18n-switcher]");
    if (!switcher) return; // ✅ Exit if switcher not found

    // Set initial value safely
    if (initialValue) switcher.value = initialValue;

    // Handle changes
    switcher.onchange = (e) => {
        const newLocale = e.target.value;
        if (newLocale) setLocale(newLocale);
    };
}

